# Записывает новый текст страницы «О компании» (o-kompanii.html рядом).
# Текст вписан в команду в base64: команду вставляют в веб-терминал
# хостинга, и в ней должна быть одна латиница. Название страницы ищется
# по точному заголовку «О компании» (тоже кодами, hex2bin); нашлось не
# ровно одна — STOP, ничего не меняется. Старый текст сохраняется
# в oc_about_before — по ней работает otkat.sh, и она же не даёт
# записать дважды. Формат хранения повторяет существующий: движок хранит
# описания с экранированием (&lt;p&gt;) и раскрывает их при выводе
# один раз; проверено, что вывод движка совпадает с o-kompanii.html
# побайтно. Проверено на MariaDB 10.11: запись, повтор, откат, нет страницы.
# Пересобрать после правки текста:
#   B64=$(base64 -w0 o-kompanii.html) и заменить строку внутри base64_decode("...").
( cd /var/www/u2934771/data/www/stroigeroi.ru || exit 1; U=$(php -r 'mysqli_report(MYSQLI_REPORT_OFF); include "config.php"; $m = @new mysqli(DB_HOSTNAME, DB_USERNAME, DB_PASSWORD, DB_DATABASE, (int)DB_PORT); if ($m->connect_error) { echo "DB: ", $m->connect_error, "\n"; exit(1); } $m->set_charset("utf8"); $p = DB_PREFIX; $new = base64_decode(""); $title = hex2bin("d09e20d0bad0bed0bcd0bfd0b0d0bdd0b8d0b8"); $r = $m->query("SELECT information_id, language_id, description FROM {$p}information_description WHERE title = \"" . $m->real_escape_string($title) . "\""); $rows = array(); while ($r && ($x = $r->fetch_row())) $rows[] = $x; if (count($rows) != 1) { echo "STOP: found ", count($rows), " pages with this title, nothing changed\n"; exit(1); } list($id, $lang, $old) = $rows[0]; if (!$m->query("CREATE TABLE {$p}about_before AS SELECT * FROM {$p}information_description WHERE information_id = " . (int)$id)) { echo "STOP: ", $m->error, " - already done, nothing changed\n"; exit(1); } $escaped = strpos($old, "&lt;") !== false; $store = $escaped ? htmlspecialchars($new, ENT_COMPAT, "UTF-8") : $new; $ok = $m->query("UPDATE {$p}information_description SET description = \"" . $m->real_escape_string($store) . "\" WHERE information_id = " . (int)$id . " AND language_id = " . (int)$lang); $k = $m->query("SELECT keyword FROM {$p}seo_url WHERE store_id = 0 AND query = \"information_id=" . (int)$id . "\" AND keyword <> \"\" LIMIT 1"); $kw = ($k && ($x = $k->fetch_row())) ? $x[0] : ""; echo "page: information_id=$id, stored ", ($escaped ? "escaped" : "as is"), ", ", strlen($old), " -> ", strlen($store), " bytes, ", ($ok ? "saved" : "SQL: " . $m->error), "\n"; echo "URL ", $kw !== "" ? $kw : "index.php?route=information/information&information_id=$id", "\n";' | tee /dev/stderr | sed -n "s/^URL //p"); [ -n "$U" ] || exit 1; H=$(curl -s "https://stroigeroi.ru/$U"); echo "tiles: $(printf %s "$H" | grep -o 'class="tile"' | wc -l), old N line: $(printf %s "$H" | grep -c 'N-')" )
